# tools/run_watermark_bench.py
from __future__ import annotations

import argparse
import csv
import importlib
import json
import sys
import traceback
from datetime import datetime
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Tuple

import numpy as np
from PIL import Image


IMG_EXTS = {".jpg", ".jpeg", ".png", ".webp", ".bmp"}
MASK_DIR_NAMES = {"mask", "masks", "label", "labels", "gt", "ground_truth", "groundtruth"}


def now() -> str:
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def norm_model_name(name: str) -> str:
    name = name.strip().lower()
    if name.startswith("watermarkseg"):
        name = name.replace("watermarkseg", "v")
    if name.isdigit():
        name = f"v{name}"
    return name


def model_versions(model_arg: Optional[str]) -> List[str]:
    if not model_arg:
        return [f"v{i}" for i in range(1, 7)]
    return [norm_model_name(x) for x in model_arg.split(",") if x.strip()]


def is_mask_path(path: Path) -> bool:
    parts = {p.lower() for p in path.parts}
    if parts & MASK_DIR_NAMES:
        return True
    s = path.stem.lower()
    return s.endswith("_mask") or s.endswith("-mask") or s.endswith("_gt") or s.endswith("-gt")


def find_mask(image_path: Path, dataset_dir: Path) -> Optional[Path]:
    stems = [
        image_path.stem,
        f"{image_path.stem}_mask",
        f"{image_path.stem}-mask",
        f"{image_path.stem}_gt",
        f"{image_path.stem}-gt",
    ]
    dirs = [dataset_dir / n for n in MASK_DIR_NAMES]
    dirs += [image_path.parent, dataset_dir]
    for d in dirs:
        if not d.exists():
            continue
        for stem in stems:
            for ext in IMG_EXTS:
                p = d / f"{stem}{ext}"
                if p.exists() and p != image_path:
                    return p
    return None


def scan_dataset(dataset_dir: Path) -> List[Tuple[Path, Path]]:
    pairs: List[Tuple[Path, Path]] = []
    for img in sorted(dataset_dir.rglob("*")):
        if not img.is_file() or img.suffix.lower() not in IMG_EXTS:
            continue
        if is_mask_path(img):
            continue
        mask = find_mask(img, dataset_dir)
        if mask:
            pairs.append((img, mask))
    return pairs


def scan_bench(root: Path, dataset_arg: Optional[str]) -> Dict[str, List[Tuple[Path, Path]]]:
    datasets: Dict[str, List[Tuple[Path, Path]]] = {}
    roots = [root / dataset_arg] if dataset_arg else [root / "generated", root / "real"]
    for d in roots:
        if d.exists():
            pairs = scan_dataset(d)
            if pairs:
                datasets[d.name] = pairs
    return datasets


def import_from_candidates(version: str) -> Any:
    n = version.replace("v", "")
    class_candidates = [f"WatermarkSegV{n}", "WatermarkSeg", "Provider"]
    modules = [
        f"phs.engines.watermark_seg_{version}",
        f"phs.engines.watermarkseg_{version}",
        "phs.engines.watermark_seg",
        f"phs.providers.watermark.watermark_seg_{version}",
        f"phs.providers.watermarkseg_{version}",
        "phs.providers.watermark.watermark_seg",
        "phs.providers.watermark_seg",
    ]
    last_err = None
    for mod_name in modules:
        try:
            mod = importlib.import_module(mod_name)
            if hasattr(mod, "create_provider"):
                try:
                    return mod.create_provider({"version": version})
                except TypeError:
                    return mod.create_provider()
            if hasattr(mod, "provider"):
                return getattr(mod, "provider")
            for cls_name in class_candidates:
                cls = getattr(mod, cls_name, None)
                if cls:
                    try:
                        return cls(version=version)
                    except TypeError:
                        return cls()
        except Exception as exc:
            last_err = exc
    raise RuntimeError(f"cannot load {version}: {last_err}")


def call_model(model: Any, image_path: Path) -> Any:
    for name in ("predict", "segment", "infer", "run", "evaluate", "detect"):
        fn = getattr(model, name, None)
        if callable(fn):
            try:
                return fn(str(image_path))
            except TypeError:
                return fn(image_path)
    if callable(model):
        return model(str(image_path))
    raise RuntimeError("model has no callable predict/segment/infer/run method")


def load_gray(path: Path, size: Optional[Tuple[int, int]] = None) -> np.ndarray:
    im = Image.open(path).convert("L")
    if size and im.size != size:
        im = im.resize(size, Image.NEAREST)
    return np.asarray(im)


def raw_to_mask(raw: Any, gt_size: Tuple[int, int], threshold: float) -> np.ndarray:
    if isinstance(raw, dict):
        for key in ("mask", "pred_mask", "seg_mask", "output", "result"):
            if key in raw:
                raw = raw[key]
                break
        if isinstance(raw, dict) and "mask_path" in raw:
            raw = raw["mask_path"]

    if isinstance(raw, (str, Path)):
        arr = load_gray(Path(raw), gt_size)
    elif isinstance(raw, Image.Image):
        im = raw.convert("L")
        if im.size != gt_size:
            im = im.resize(gt_size, Image.NEAREST)
        arr = np.asarray(im)
    else:
        arr = np.asarray(raw)
        if arr.ndim == 3:
            arr = arr.mean(axis=2)
        if arr.shape[:2] != (gt_size[1], gt_size[0]):
            im = Image.fromarray(arr.astype("uint8") if arr.max() > 1 else (arr * 255).astype("uint8"))
            im = im.resize(gt_size, Image.NEAREST)
            arr = np.asarray(im)

    arr = arr.astype("float32")
    if arr.max() > 1.0:
        arr = arr / 255.0
    return arr >= threshold


def metrics(pred: np.ndarray, gt: np.ndarray) -> Dict[str, float]:
    pred = pred.astype(bool)
    gt = gt.astype(bool)
    tp = float(np.logical_and(pred, gt).sum())
    fp = float(np.logical_and(pred, ~gt).sum())
    fn = float(np.logical_and(~pred, gt).sum())
    union = float(np.logical_or(pred, gt).sum())
    precision = tp / (tp + fp + 1e-9)
    recall = tp / (tp + fn + 1e-9)
    f1 = 2 * precision * recall / (precision + recall + 1e-9)
    iou = tp / (union + 1e-9)
    return {"iou": iou, "precision": precision, "recall": recall, "f1": f1}


def mean_metrics(rows: List[Dict[str, Any]]) -> Dict[str, float]:
    if not rows:
        return {"iou": 0.0, "precision": 0.0, "recall": 0.0, "f1": 0.0}
    return {k: sum(float(r[k]) for r in rows) / len(rows) for k in ("iou", "precision", "recall", "f1")}


def run_one(model_name: str, model: Any, dataset: str, pairs: List[Tuple[Path, Path]], threshold: float) -> Dict[str, Any]:
    rows, errors = [], []
    for img, mask_path in pairs:
        try:
            gt_arr = load_gray(mask_path)
            gt = gt_arr >= 128
            pred = raw_to_mask(call_model(model, img), Image.open(mask_path).size, threshold)
            m = metrics(pred, gt)
            rows.append({"image": str(img), "mask": str(mask_path), **m})
        except Exception as exc:
            errors.append({"image": str(img), "error": f"{type(exc).__name__}: {exc}"})
    avg = mean_metrics(rows)
    return {"model": model_name, "dataset": dataset, "count": len(rows), "errors": errors, **avg, "rows": rows}


def md_table(results: List[Dict[str, Any]]) -> str:
    lines = [
        "| Model | Dataset | Count | IoU | Precision | Recall | F1 | Errors |",
        "|---|---|---:|---:|---:|---:|---:|---:|",
    ]
    for r in results:
        lines.append(
            f"| {r['model']} | {r['dataset']} | {r['count']} | "
            f"{r['iou']:.4f} | {r['precision']:.4f} | {r['recall']:.4f} | {r['f1']:.4f} | {len(r['errors'])} |"
        )
    return "\n".join(lines)


def write_outputs(out_dir: Path, results: List[Dict[str, Any]], args: argparse.Namespace) -> None:
    out_dir.mkdir(parents=True, exist_ok=True)
    csv_path = out_dir / "watermark_bench_summary.csv"
    json_path = out_dir / "watermark_bench_detail.json"
    md_path = out_dir / "watermark_bench_report.md"

    with csv_path.open("w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=["model", "dataset", "count", "iou", "precision", "recall", "f1", "errors"])
        w.writeheader()
        for r in results:
            w.writerow({k: r.get(k) for k in ("model", "dataset", "count", "iou", "precision", "recall", "f1")} | {"errors": len(r["errors"])})

    json_path.write_text(json.dumps(results, ensure_ascii=False, indent=2), encoding="utf-8")
    report = [
        "# WatermarkSeg 基准跑分报告",
        "",
        f"- 时间：{now()}",
        f"- 根目录：`{args.root}`",
        f"- 模型：`{args.model or 'v1-v6'}`",
        f"- 数据集：`{args.dataset or 'generated + real'}`",
        f"- 阈值：`{args.threshold}`",
        "",
        "## 对比表",
        "",
        md_table(results),
        "",
        "## 输出文件",
        "",
        f"- `{csv_path}`",
        f"- `{json_path}`",
    ]
    md_path.write_text("\n".join(report), encoding="utf-8")
    print(md_table(results))
    print(f"\nreport: {md_path}")


def main() -> int:
    parser = argparse.ArgumentParser(description="Run WatermarkSeg v1-v6 benchmark.")
    parser.add_argument("--root", default="benchmarks/watermark", help="benchmark root directory")
    parser.add_argument("--model", default=None, help="single model or comma list, e.g. v3 or v1,v2")
    parser.add_argument("--dataset", default=None, help="single dataset under root, e.g. generated or real")
    parser.add_argument("--threshold", type=float, default=0.5, help="mask binarization threshold")
    args = parser.parse_args()

    root = Path(args.root)
    out_dir = root / "results"
    datasets = scan_bench(root, args.dataset)
    if not datasets:
        print(f"No dataset pairs found under {root}", file=sys.stderr)
        return 2

    results: List[Dict[str, Any]] = []
    for mv in model_versions(args.model):
        try:
            model = import_from_candidates(mv)
        except Exception as exc:
            for ds in datasets:
                results.append({"model": mv, "dataset": ds, "count": 0, "iou": 0, "precision": 0, "recall": 0, "f1": 0,
                                "errors": [{"load_error": str(exc), "trace": traceback.format_exc()}], "rows": []})
            continue
        for ds, pairs in datasets.items():
            results.append(run_one(mv, model, ds, pairs, args.threshold))

    write_outputs(out_dir, results, args)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
